#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Ticket 46's by-hand checks in a real nested Camino. Run it from a terminal on
# the host desktop, with tools/dev-nested running in a second terminal. Each
# result is appended to the ticket's notes, and a passing criterion is ticked.
# Results are saved as they're given, so a stopped run resumes where it left off.

TOTAL_STAGES=11

TICKET="$(dirname "$(realpath "$0")")/46-nested-x11-checks-left-over.md"
RESULTS=()   # "prefix|short name|pass or FAIL|note"
FAILED=()
PROGRESS="${XDG_STATE_HOME:-$HOME/.local/state}/camino/46-hand-checks.progress"
DEMO_OPEN=

# x11 CMD... starts an X11 client on the nested Xwayland, detached. GTK apps get
# their own session bus, so they can't hand off to an instance on the host's.
x11() {
  env -u WAYLAND_DISPLAY DISPLAY=":$NESTED_X" GDK_BACKEND=x11 \
    setsid dbus-run-session -- "$@" >/dev/null 2>&1 &
}
# native CMD... starts a Wayland client on the nested Camino, detached.
native() {
  env -u DISPLAY WAYLAND_DISPLAY="$NESTED_WL" GDK_BACKEND=wayland \
    setsid dbus-run-session -- "$@" >/dev/null 2>&1 &
}
# xterm with a fixed title, so `wmctrl -r xterm` finds it by title as the ticket runs it.
nested_xterm() { x11 xterm -T xterm -xrm 'XTerm*allowTitleOps: false'; }
# nx CMD... runs an X command against the nested Xwayland and shows its output.
nx() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; env DISPLAY=":$NESTED_X" "$@" 2>&1 | sed 's/^/    /'; }

# read_nested asks for the line tools/dev-nested prints once Xwayland is ready.
read_nested() {
  local line
  while true; do
    printf '  %sPaste the line "dev-nested: WAYLAND_DISPLAY=… DISPLAY=:…":%s ' "$BOLD" "$RESET"
    read -r line || true
    if [[ $line =~ WAYLAND_DISPLAY=(wayland-[0-9]+)\ DISPLAY=:([0-9]+) ]]; then
      NESTED_WL=${BASH_REMATCH[1]}; NESTED_X=${BASH_REMATCH[2]}
      printf '  %s✓%s nested WAYLAND_DISPLAY=%s DISPLAY=:%s\n' "$GREEN" "$RESET" "$NESTED_WL" "$NESTED_X"
      return
    fi
    warn "that isn't the dev-nested line; try again"
  done
}

# result PREFIX "Short name" records whether the criterion starting with PREFIX
# passed, with an optional note.
result() {
  local prefix="$1" name="$2" verdict note=""
  if confirm "Did all of it work? ($name)"; then verdict=pass; else verdict=FAIL; FAILED+=("$name"); fi
  printf '  %sNote (what you saw; Enter for none):%s ' "$BOLD" "$RESET"
  read -r note || true
  RESULTS+=("$prefix|$name|$verdict|$note")
  printf '%s|%s|%s|%s\n' "$prefix" "$name" "$verdict" "$note" >> "$PROGRESS"
}

# load_progress offers to resume from the results a stopped run saved.
load_progress() {
  local r name verdict note
  mkdir -p "$(dirname "$PROGRESS")"
  [[ -s $PROGRESS ]] || return 0
  say "A stopped run saved these results:"
  while IFS= read -r r; do
    IFS='|' read -r _ name verdict note <<< "$r"
    say "  $verdict  $name${note:+ ($note)}"
  done < "$PROGRESS"
  if confirm "Resume, skipping the stages they cover? (No starts over)"; then
    mapfile -t RESULTS < "$PROGRESS"
    for r in "${RESULTS[@]}"; do
      IFS='|' read -r _ name verdict _ <<< "$r"
      [[ $verdict == FAIL ]] && FAILED+=("$name")
    done
  else
    : > "$PROGRESS"
  fi
}

# done_already NAME... succeeds, and says so, when every named result is recorded.
done_already() {
  local name
  for name in "$@"; do
    printf '%s\n' "${RESULTS[@]}" | grep -qF "|$name|" || return 1
  done
  say "Already recorded; skipping."
  sleep 1
}

# ensure_xterm opens the nested xterm unless one titled "xterm" is already open.
ensure_xterm() {
  env DISPLAY=":$NESTED_X" wmctrl -l 2>/dev/null | awk '$NF == "xterm" {f=1} END {exit !f}' || nested_xterm
}
# ensure_demo opens the nested gtk3-demo unless this run already did.
ensure_demo() {
  [[ -n $DEMO_OPEN ]] || x11 gtk3-demo --run=application_demo
  DEMO_OPEN=1
}

# write_results appends the results to the ticket's notes and ticks each criterion
# whose results all passed.
write_results() {
  local r prefix name verdict note today
  today=$(date +%F)
  grep -q '^## Notes' "$TICKET" || printf '\n## Notes\n' >> "$TICKET"
  printf '\n- **By hand (%s):**\n' "$today" >> "$TICKET"
  for r in "${RESULTS[@]}"; do
    IFS='|' read -r prefix name verdict note <<< "$r"
    printf '  - %s: %s.%s\n' "$name" "$verdict" "${note:+ $note}" >> "$TICKET"
  done
  for r in "${RESULTS[@]}"; do
    IFS='|' read -r prefix _ verdict _ <<< "$r"
    printf '%s\n' "${RESULTS[@]}" | grep -qF "$prefix|" && \
      ! printf '%s\n' "${RESULTS[@]}" | grep -F "$prefix|" | grep -qF '|FAIL|' && \
      PREFIX="$prefix" perl -0pi -e 's/^- \[ \] (\Q$ENV{PREFIX}\E)/- [x] $1/m' "$TICKET"
  done
  printf '  %s✓ wrote%s %s results to %s\n' "$GREEN" "$RESET" "${#RESULTS[@]}" "$TICKET"
}

banner "Ticket 46: nested X11 checks by hand"
load_progress

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Start the nested Camino"
say "Run this on the host desktop, not on a tty."
for tool in xterm xeyes wmctrl xprop foot caja gtk3-demo; do
  command -v "$tool" >/dev/null || warn "$tool is missing (pacman -S xterm xorg-xeyes wmctrl xorg-xprop)"
done
step "In a second terminal, from the checkout, run:  tools/dev-nested --bin"
step "Wait for its line  dev-nested: WAYLAND_DISPLAY=wayland-N DISPLAY=:M"
read_nested

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "gtk3-demo's tooltip on the host, without Camino"
if ! done_already "gtk3-demo's tooltip on the host"; then
say "Opening gtk3-demo's Application Class demo on the host's own display."
env GDK_BACKEND=x11 setsid dbus-run-session -- gtk3-demo --run=application_demo >/dev/null 2>&1 &
step "Hover the toolbar's New button. Its tooltip should read \"Create a new file\"."
step "If it doesn't show, find another widget in this demo whose tooltip does, and"
step "write down which one in the note. The next stage uses the same widget."
result "On the host desktop, without Camino" "gtk3-demo's tooltip on the host"
say "Close the host's gtk3-demo now."
pause
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "gtk3-demo's tooltip, nested"
if ! done_already "The tooltip, nested"; then
say "Opening the same demo on the nested Xwayland (:$NESTED_X)."
ensure_demo
step "Hover the same widget as before, with the real pointer."
step "The tooltip shows above the window, not behind it."
step "Move the pointer off the widget: the tooltip goes away."
result "Nested, that tooltip" "The tooltip, nested"
say "Leave gtk3-demo open; the menus are next."
pause
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Menus by hand"
if ! done_already "Menus by hand"; then
ensure_demo
step "Click the demo's Preferences menu. It opens, above its window."
step "Press Down to move through it, then Right on Color to open its submenu."
step "Press Escape to back out of the submenu, then open it again."
step "Click outside the menu, on the empty output: the menu closes."
step "Click in the demo's text area and type: the text goes to the window."
result "Nested, gtk3-demo's Preferences menu" "Menus by hand"
say "Close the nested gtk3-demo."
pause
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "xterm and xeyes"
if ! done_already "xterm and xeyes"; then
say "Opening xterm and xeyes on :$NESTED_X."
ensure_xterm
x11 xeyes
step "Both map with Menta frames (Camino's titlebar and border)."
step "Click one, then the other: each takes focus, its frame going active."
step "Drag each by its titlebar: it moves."
step "Type in xterm (echo hello): the text goes to it."
step "Move the pointer all over Camino's output: xeyes's eyes follow it everywhere."
result "Nested, xterm and xeyes" "xterm and xeyes"
say "Close xeyes; keep xterm open."
pause
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Clipboard and primary selection, xterm and foot"
if ! done_already "Clipboard and primary, xterm and foot"; then
ensure_xterm
say "Opening a native foot on $NESTED_WL."
native foot
step "Primary, xterm → foot: select text in xterm, middle-click in foot."
step "Primary, foot → xterm: select text in foot, middle-click in xterm."
step "In xterm, Ctrl+middle-click opens VT Options: turn on \"Select to Clipboard\"."
note "xterm then copies its selection to the clipboard and pastes from it."
step "Clipboard, xterm → foot: select text in xterm, Ctrl+Shift+V in foot."
step "Clipboard, foot → xterm: select text in foot, Ctrl+Shift+C, middle-click in xterm."
result "Nested, text copied in xterm" "Clipboard and primary, xterm and foot"
pause
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Drag and drop, caja on X11 and native caja"
if ! done_already "Drag and drop, caja on X11 and native caja"; then
say "Opening caja on :$NESTED_X and a native caja on $NESTED_WL, each in its own /tmp folder."
mkdir -p /tmp/camino-dnd-x11 /tmp/camino-dnd-native
: > /tmp/camino-dnd-x11/from-x11.txt
: > /tmp/camino-dnd-native/from-native.txt
x11 caja --no-desktop /tmp/camino-dnd-x11
native caja --no-desktop /tmp/camino-dnd-native
step "Drag from-x11.txt from the X11 caja (/tmp/camino-dnd-x11) into the native one."
step "Drag from-native.txt from the native caja (/tmp/camino-dnd-native) into the X11 one."
step "Each drop copies or moves the file into the other folder."
note "Criterion 5 is ticked only if this and the clipboard stage both pass."
result "Nested, text copied in xterm" "Drag and drop, caja on X11 and native caja"
say "Close both cajas."
pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Frame extents and workspaces"
if ! done_already "Frame extents and wmctrl -t" "wmctrl -d and -s"; then
ensure_xterm
sleep 1
say "Running the checks against the open xterm (titled \"xterm\")."
nx sh -c 'xprop -id "$(wmctrl -l | awk "\$NF == \"xterm\" {print \$1; exit}")" _NET_FRAME_EXTENTS'
note "The Menta frame is 1, 1, 31, 1 (left, right, top, bottom)."
nx wmctrl -d
note "Expected: Workspace 1 to Workspace 4, with * on the first."
nx wmctrl -r xterm -t 1
nx wmctrl -l
note "Expected: xterm on desktop 1, and gone from the output."
nx wmctrl -s 2
nx wmctrl -d
note "Expected: * on Workspace 3."
nx wmctrl -s 1
step "Check xterm is back on screen on Workspace 2, then:"
nx wmctrl -s 0
result "Nested, \`xprop\` on an xterm" "Frame extents and wmctrl -t"
result "Nested, \`wmctrl -d\`" "wmctrl -d and -s"
pause
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "xterm after an Xwayland restart"
if ! done_already "xterm after an Xwayland restart"; then
ensure_xterm
say "A fresh xterm is opening on :$NESTED_X."
XW_PID=$(ps -eo pid=,args= | awk -v d=":$NESTED_X" '$2 ~ /Xwayland$/ && $3 == d {print $1}')
if [[ -z $XW_PID ]]; then
  warn "couldn't find the nested Xwayland on :$NESTED_X; find it with  ps -eo pid,args | grep Xwayland"
  ask XW_PID "Its pid:"
fi
say "The nested Xwayland is pid $XW_PID:"
ps -o pid=,args= -p "$XW_PID" | sed 's/^/    /'
if confirm "Kill it (SIGKILL)?"; then
  kill -9 "$XW_PID"
  step "Every xterm disappears from Camino's output, and the dev-nested terminal logs"
  step "the restart, then a new  dev-nested: … DISPLAY=:$NESTED_X  line."
  pause "Press Enter once that line appears"
  nested_xterm
  step "A new xterm maps on the same DISPLAY, with a Menta frame."
  result "Nested, killing the nested Xwayland" "xterm after an Xwayland restart"
else
  SKIPPED+=("the Xwayland restart check")
fi
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "xterm at scale 2"
if ! done_already "xterm at scale 2"; then
step "Stop dev-nested (Ctrl+C) and start it again with:  tools/dev-nested --bin --scale 2"
read_nested
nested_xterm
step "xterm's text renders sharp, not blurred, inside a Menta frame at scale 2."
pause "Press Enter once it's open"
nx sh -c 'xprop -id "$(wmctrl -l | awk "\$NF == \"xterm\" {print \$1; exit}")" _NET_FRAME_EXTENTS'
note "Expected: 2, 2, 62, 2, twice the frame's 1, 1, 31, 1."
result "Nested with \`tools/dev-nested --bin --scale 2\`" "xterm at scale 2"
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Record the results"
for r in "${RESULTS[@]}"; do
  IFS='|' read -r _ name verdict note <<< "$r"
  say "$verdict  $name${note:+ ($note)}"
done
if confirm "Write these to the ticket's notes?"; then
  write_results
  rm -f "$PROGRESS"
  (( ${#FAILED[@]} )) && SKIPPED+=("a new ticket for each failure: ${FAILED[*]}")
else
  SKIPPED+=("recording the results in ticket 46 (they stay in $PROGRESS)")
fi
say "Stop dev-nested with Ctrl+C when you're done."
pause

finish
